// 🧭 Array parameter owner FIRST
export function touch(a: f64[], i: u32, value: f64): f64 {
  a[i] = value;
  return a[i];
}
export function entry(i: u32, value: f64): f64 {
  const actual: f64[] = [1.0, 2.0];
  const alias = actual;
  return touch(alias, i, value);
}

